import {inheritTraits} from './simulation/life-traits.mjs';
import {createLifeWorld,createIndividual,experience,relate,endLife,successor,activity,compactLifeWorld} from './simulation/life-story.mjs';
import {inventIdentity} from './town-life/people/core.mjs';
export function ensureStories(state,seed){return state.lifeStories??=createLifeWorld('ranch-'+seed);}
export function syncHumanStories(world,people,year){
 for(const p of people){p.storyId??=world.namespace+':person:'+p.id;if(!p.alive&&p.storyRecorded&&!world.entities[p.storyId])continue;p.storyRecorded=true;const e=world.entities[p.storyId]??createIndividual(world,{id:p.storyId,type:'human',label:inventIdentity(p).name,generation:p.generation,born:p.born,origin:{kind:'arrival',sources:[]},traits:p.appearance,capabilities:['household','schedule','family']});if(e.age!==p.age){e.age=p.age;experience(world,e.id,'age',year,{age:p.age});}if(!p.alive)endLife(world,e.id,p.born+p.deathAge,'old age');}
 for(const p of people){const e=world.entities[p.storyId];if(!e)continue;e.currentPartner=p.spouse?people.find(q=>q.id===p.spouse)?.storyId??null:null;if(p.parents?.length&&e.origin.kind==='arrival'){const sources=p.parents.map(id=>people.find(q=>q.id===id)?.storyId).filter(id=>id&&world.entities[id]);e.origin={kind:'family-lineage',sources};for(const parent of sources){relate(world,parent,e.id,'child',p.born);relate(world,e.id,parent,'parent',p.born);}}
 if(p.spouse){const spouse=people.find(q=>q.id===p.spouse);if(spouse&&world.entities[spouse.storyId])relate(world,e.id,spouse.storyId,'spouse-history',year);}
 }
}
export function ensureOrganism(world,{slot,type,label,born,traits={},capabilities=[],detail='full'}){const existing=world.occupants[slot];if(existing&&world.entities[existing])return world.entities[existing];const e=createIndividual(world,{type,label,born,traits,capabilities,detail});world.occupants[slot]=e.id;return e;}
export function advanceOrganism(world,slot,{year,span,type,label,originKind='arrival',biological=false,traits={},capabilities=[],traitSchema}){if(!Number.isFinite(span)||span<=0||!Number.isFinite(year))throw Error('Invalid lifecycle time');let e=world.entities[world.occupants[slot]];if(!e)throw Error('Unknown organism slot: '+slot);const previous=e.id;if(traitSchema)world.definitions[type].traits??=traitSchema;while(year-e.lifecycle.born>=span){const at=e.lifecycle.born+span;e=successor(world,slot,e.id,{at,type,label,originKind,sources:biological?[e.id]:[],traits:traitSchema?inheritTraits(traitSchema,[e.traits],e.id+':offspring'):traits,capabilities});}if(e.id!==previous)compactLifeWorld(world);return e;}
export function recordActivity(world,id,value,year){activity(world,id,value,year);}

export const ANIMAL_TRAITS={size:{default:.97,min:.92,max:1,variation:.02},pace:{default:1,min:.9,max:1.1,variation:.04}};
export const PLANT_TRAITS={bloom:{default:1,min:.8,max:1.2,variation:.08}};
export function compactFamilies(family,world){const dead=family.people.filter(p=>!p.alive).sort((a,b)=>(b.born+b.deathAge)-(a.born+a.deathAge)),removed=new Set(dead.slice(64).map(p=>p.id));if(!removed.size)return;const lookup=new Map(family.people.map(p=>[p.id,p]));for(const p of family.people){const lost=(p.parents||[]).filter(id=>removed.has(id));if(lost.length)p.summarizedParents=lost.map(id=>({id,name:inventIdentity(lookup.get(id)).name,generation:lookup.get(id).generation,detailAvailable:false}));p.parents=(p.parents||[]).filter(id=>!removed.has(id));p.children=(p.children||[]).filter(id=>!removed.has(id));}family.people=family.people.filter(p=>!removed.has(p.id));compactLifeWorld(world);}
